/* Masks, gradient stacks and the drift loops: none of these fit in utilities. */
@layer kg.components {
  .kg-aurora {
    &[data-mask="radial"] > .kg-aurora__layer {
      mask-image: radial-gradient(ellipse 80% 75% at 50% 30%, #000 25%, transparent 100%);
    }

    &[data-mask="top"] > .kg-aurora__layer {
      mask-image: radial-gradient(ellipse 100% 85% at 50% 0%, #000 30%, transparent 100%);
    }

    &[data-mask="bottom"] > .kg-aurora__layer {
      mask-image: radial-gradient(ellipse 100% 85% at 50% 100%, #000 30%, transparent 100%);
    }

    &[data-mask="edges"] > .kg-aurora__layer {
      mask-image:
        linear-gradient(to right, transparent, #000 15% 85%, transparent),
        linear-gradient(to bottom, transparent, #000 15% 85%, transparent);
      mask-composite: intersect;
    }
  }

  /* One tile equals the layer width, so translating by one tile loops seamlessly. */
  .kg-aurora__curtain {
    background-image: linear-gradient(
      90deg,
      transparent 0%,
      var(--_c1) 10%,
      transparent 22%,
      var(--_c2) 34%,
      transparent 46%,
      var(--_c3) 60%,
      transparent 72%,
      var(--_c1) 84%,
      transparent 100%
    );
    background-size: 40% 100%;
    mask-image: linear-gradient(to bottom, #000 5%, transparent 95%);
    transform: skewX(-16deg) translate3d(-12%, 0, 0);
    animation: kg-aurora-curtain calc(56s / var(--kg-aurora-speed, 1)) linear infinite;
  }

  /* A long gradient falloff reads as blur without a filter on a viewport-sized layer. */
  .kg-aurora__light {
    background: radial-gradient(
      closest-side,
      var(--_c),
      color-mix(in oklab, var(--_c) 45%, transparent) 45%,
      color-mix(in oklab, var(--_c) 12%, transparent) 75%,
      transparent
    );
    animation: kg-aurora-drift-a calc(22s / var(--kg-aurora-speed, 1)) var(--kg-ease-in-out) infinite
      alternate;

    &[data-light="1"] {
      --_c: var(--_c1);
    }

    &[data-light="2"] {
      --_c: var(--_c2);
      animation-name: kg-aurora-drift-b;
      animation-duration: calc(28s / var(--kg-aurora-speed, 1));
    }

    &[data-light="3"] {
      --_c: var(--_c3);
      animation-name: kg-aurora-drift-c;
      animation-duration: calc(34s / var(--kg-aurora-speed, 1));
    }
  }

  .kg-aurora__ribbon {
    background: linear-gradient(
      90deg,
      transparent 4%,
      var(--_c2) 28%,
      var(--_c1) 50%,
      var(--_c3) 72%,
      transparent 96%
    );
    mask-image: radial-gradient(closest-side, #000 20%, transparent);
    transform: rotate(-4deg);
    animation: kg-aurora-ribbon calc(26s / var(--kg-aurora-speed, 1)) var(--kg-ease-in-out) infinite
      alternate;
  }

  @media (prefers-reduced-motion: reduce) {
    .kg-aurora__layer > * {
      animation: none;
    }
  }

  [data-kg-motion="reduce"] .kg-aurora__layer > * {
    animation: none;
  }

  @keyframes kg-aurora-curtain {
    from {
      transform: skewX(-16deg) translate3d(0, 0, 0);
    }
    to {
      transform: skewX(-16deg) translate3d(-40%, 0, 0);
    }
  }

  @keyframes kg-aurora-drift-a {
    from {
      transform: translate3d(-6%, -4%, 0) scale(0.95);
    }
    to {
      transform: translate3d(16%, 10%, 0) scale(1.15);
    }
  }

  @keyframes kg-aurora-drift-b {
    from {
      transform: translate3d(8%, 2%, 0) scale(1.1);
    }
    to {
      transform: translate3d(-14%, 12%, 0) scale(0.9);
    }
  }

  @keyframes kg-aurora-drift-c {
    from {
      transform: translate3d(-18%, 4%, 0) scale(0.9);
    }
    to {
      transform: translate3d(20%, -8%, 0) scale(1.2);
    }
  }

  @keyframes kg-aurora-ribbon {
    from {
      transform: translate3d(-6%, -4%, 0) rotate(-9deg) scaleY(0.8);
    }
    to {
      transform: translate3d(6%, 14%, 0) rotate(5deg) scaleY(1.2);
    }
  }
}

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
} from "react"
import { type BackdropMask, backdropRoot, hasChildren } from "./internal/backdrop"

export type AuroraMask = BackdropMask

export interface AuroraProps extends HTMLAttributes<HTMLDivElement> {
  /** Up to three CSS colors. Defaults to the sage, sky and peach papers, so it follows the theme. */
  colors?: readonly string[]
  /** Overall strength, 0–1. */
  intensity?: number
  /** Blur radius of each light, in px. */
  blur?: number
  /** Drift speed multiplier; 1 completes a cycle in roughly 20 seconds. */
  speed?: number
  /** Fade the effect out toward the edges. */
  mask?: AuroraMask
  /** Optional content, painted above the aurora. */
  children?: ReactNode
}

/**
 * Slow, heavily blurred ribbons of light. Each layer drifts on its own transform-only loop, so the
 * compositor does the work and the page never repaints. Pure CSS: server-component safe.
 */
export const Aurora = forwardRef<HTMLDivElement, AuroraProps>(
  (
    {
      colors,
      intensity = 0.6,
      blur = 64,
      speed = 1,
      mask = "radial",
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const wrapper = hasChildren(children)
    const [c1, c2, c3] = colors ?? []

    return (
      <div
        ref={ref}
        {...backdropRoot(
          "kg-aurora absolute inset-0 overflow-hidden pointer-events-none data-wrapper:relative data-wrapper:inset-auto data-wrapper:overflow-visible data-wrapper:isolate data-wrapper:pointer-events-auto [--_c1:var(--kg-aurora-color-1,var(--kg-paper-sage))] [--_c2:var(--kg-aurora-color-2,var(--kg-paper-sky))] [--_c3:var(--kg-aurora-color-3,var(--kg-paper-peach))]",
          className,
          wrapper,
        )}
        data-mask={mask}
        style={
          {
            ...(c1 ? { "--kg-aurora-color-1": c1 } : null),
            ...(c2 ? { "--kg-aurora-color-2": c2 } : null),
            ...(c3 ? { "--kg-aurora-color-3": c3 } : null),
            "--kg-aurora-intensity": Math.min(Math.max(intensity, 0), 1),
            "--kg-aurora-blur": `${Math.max(blur, 0)}px`,
            "--kg-aurora-speed": Math.max(speed, 0.01),
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        <div
          className="kg-aurora__layer pointer-events-none absolute inset-0 z-0 overflow-hidden opacity-[var(--kg-aurora-intensity)] [container-type:size]"
          aria-hidden="true"
        >
          <div className="kg-aurora__curtain absolute top-[-20%] left-0 h-[95%] w-[250%] origin-top-left opacity-50 blur-[calc(var(--kg-aurora-blur)*0.3)] will-change-transform" />
          <div
            className="kg-aurora__light absolute top-[-32cqmax] left-[-12cqmax] aspect-square w-[70cqmax] rounded-full will-change-transform"
            data-light="1"
          />
          <div
            className="kg-aurora__light absolute top-[-28cqmax] right-[-14cqmax] aspect-square w-[62cqmax] rounded-full opacity-85 will-change-transform"
            data-light="2"
          />
          <div
            className="kg-aurora__light absolute top-[-6cqmax] left-[24cqmax] aspect-square w-[46cqmax] rounded-full opacity-70 will-change-transform"
            data-light="3"
          />
          <div className="kg-aurora__ribbon absolute top-[4%] left-[-20%] h-[42%] w-[140%] opacity-65 blur-[calc(var(--kg-aurora-blur)*0.6)] will-change-transform" />
        </div>
        {wrapper && <div className="kg-aurora__content relative z-1">{children}</div>}
      </div>
    )
  },
)

Aurora.displayName = "Aurora"

/**
 * mulberry32: a tiny PRNG that yields the same sequence on the server and in the browser for a
 * given seed, so randomised backgrounds hydrate without markup mismatches.
 */
export const createRandom = (seed: number): (() => number) => {
  let state = Math.imul(Math.trunc(seed) ^ 0x9e3779b9, 0x85ebca6b) >>> 0
  return () => {
    state = (state + 0x6d2b79f5) | 0
    let t = Math.imul(state ^ (state >>> 15), 1 | state)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** Fixed precision keeps serialised styles short and identical across runtimes. */
export const round = (value: number, digits = 3): number => {
  const factor = 10 ** digits
  return Math.round(value * factor) / factor
}
